def odd_one_out(s):
    count = {}
    last_index = {}

    for i, char in enumerate(s):
        count[char] = count.get(char, 0) + 1
        last_index[char] = i

    unpaired = []
    for char, cnt in count.items():
        if cnt % 2 == 1:
            unpaired.append((last_index[char], char))

    unpaired.sort(key=lambda x: x[0])

    return [char for _, char in unpaired]
